beforeEach(() => {
    vi.resetModules();
    createRoot.mockClear();
    render.mockClear();
    document.body.innerHTML = '<div id="root"></div>';
    delete (globalThis.crypto as Crypto & { randomUUID?: Crypto["randomUUID"] }).randomUUID;
  })

afterEach(() => {
    Object.defineProperty(globalThis.crypto, "randomUUID", {
      value: originalRandomUUID,
      configurable: true,
    });
    document.body.innerHTML = "";
  })

beforeEach(() => {
  calls = []
  mockResponse = { status: 200, body: {} }
  process.env.LETSFG_API_URL = 'https://api.test.local'
  process.env.LETSFG_WEBSITE_API_KEY = 'test-website-key'
  globalThis.fetch = (async (input: RequestInfo | URL, init: RequestInit = {}) => {
    calls.push({ url: input.toString(), init })
    return {
      ok: mockResponse.status >= 200 && mockResponse.status < 300,
      status: mockResponse.status,
      json: async () => mockResponse.body,
      text: async () => JSON.stringify(mockResponse.body),
    } as unknown as Response
  }) as typeof fetch
})

beforeEach(() => {
  fetchMock = mock.fn(async (url: string) => {
    // Return a "tweet not found" for any URL containing "missing"
    if (url.includes('missing')) {
      return { ok: false, json: async () => ({}) }
    }
    // Return a real-looking oEmbed response otherwise
    const handle = 'devhandle'
    const tweetText = url.includes('wrongcode')
      ? 'This tweet has no challenge code at all'
      : `I'm getting free programmatic flight search from @LetsFG ✈️ Challenge: PLACEHOLDER https://letsfg.co/for-agents`
    return { ok: true, json: async () => makeMockOembedResponse(tweetText, handle) }
  })
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  ;(globalThis as any).fetch = fetchMock
})

beforeEach(async () => {
  // Reset modules to get fresh state
  vi.resetModules();

  // Re-import to trigger module init
  const axiosMod = await import('axios');
  const mockCreate = axiosMod.default.create as unknown as ReturnType<typeof vi.fn>;

  // Get the mock instance that create() returns
  const mockInstance = mockCreate.mock.results[0]?.value;
  if (!mockInstance) {
    // Trigger module load
    await import('./api');
    const instance = mockCreate.mock.results[0]?.value;
    if (instance) {
      const responseCalls = instance.interceptors.response.use.mock.calls;
      if (responseCalls.length > 0) {
        _interceptorSuccessHandler = responseCalls[0][0];
        _interceptorErrorHandler = responseCalls[0][1];
      }
    }
  }
})

beforeAll(async () => {
    sandbox = await Sandbox.create({
      image: getSandboxImage(),
      connectionConfig: createConnectionConfig(),
      extensions: { "bootstrap.execd.isolation": "enable" },
    });

    const caps = await sandbox.isolation.capabilities();
    console.log(
      `Isolation capabilities: available=${caps.available} isolator=${caps.isolator} version=${caps.version} message=${caps.message}`
    );
    if (!caps.available) {
      throw new Error(`Isolation NOT available: ${caps.message ?? "unknown reason"}`);
    }
  }, 120_000)

afterAll(async () => {
    if (sandbox) {
      await sandbox.kill();
      await sandbox.close();
    }
  })

beforeAll(async () => {
  try {
    const duck = await import('@duckdb/node-api');
    const instance = await duck.DuckDBInstance.create(':memory:');
    connection = (await instance.connect()) as unknown as DuckDBConnectionLike;
    source = createNodeApiDuckSource(connection);
  } catch (err) {
    console.warn(
      '[spike] @duckdb/node-api not available, skipping DuckDB spike:',
      (err as Error).message,
    );
  }
})

