beforeEach(async () => {
  // Create temporary test directory
  testDir = await fs.mkdtemp(path.join(os.tmpdir(), 'api-debugger-test-'));

  // Create sample OpenAPI spec
  const openAPISpec = {
    openapi: '3.0.0',
    info: {
      title: 'Test API',
      version: '1.0.0',
      description: 'A test API for debugging'
    },
    servers: [
      {
        url: 'https://api.example.com/v1'
      }
    ],
    paths: {
      '/users/{id}': {
        get: {
          summary: 'Get user by ID',
          parameters: [
            {
              name: 'id',
              in: 'path',
              required: true,
              schema: { type: 'string' }
            }
          ],
          responses: {
            '200': {
              description: 'Success',
              content: {
                'application/json': {
                  schema: {
                    type: 'object',
                    properties: {
                      id: { type: 'string' },
                      name: { type: 'string' }
                    }
                  }
                }
              }
            },
            '404': {
              description: 'User not found'
            }
          }
        }
      },
      '/users': {
        post: {
          summary: 'Create user',
          requestBody: {
            required: true,
            content: {
              'application/json': {
                schema: {
                  type: 'object',
                  required: ['name', 'email'],
                  properties: {
                    name: { type: 'string' },
                    email: { type: 'string', format: 'email' }
                  }
                }
              }
            }
          },
          responses: {
            '201': {
              description: 'Created'
            },
            '400': {
              description: 'Bad request'
            }
          }
        }
      }
    }
  };

  openAPISpecPath = path.join(testDir, 'openapi.json');
  await fs.writeFile(openAPISpecPath, JSON.stringify(openAPISpec, null, 2));

  // Create sample HAR file
  const harFile = {
    log: {
      version: '1.2',
      creator: {
        name: 'Test',
        version: '1.0'
      },
      entries: [
        {
          startedDateTime: '2025-10-10T12:00:00.000Z',
          time: 150,
          request: {
            method: 'GET',
            url: 'https://api.example.com/v1/users/123',
            headers: [
              { name: 'Authorization', value: 'Bearer token123' },
              { name: 'Accept', value: 'application/json' }
            ]
          },
          response: {
            status: 200,
            headers: [
              { name: 'Content-Type', value: 'application/json' }
            ],
            content: {
              text: JSON.stringify({ id: '123', name: 'John Doe' })
            }
          }
        },
        {
          startedDateTime: '2025-10-10T12:01:00.000Z',
          time: 50,
          request: {
            method: 'POST',
            url: 'https://api.example.com/v1/users',
            headers: [
              { name: 'Content-Type', value: 'application/json' }
            ],
            postData: {
              text: JSON.stringify({ name: 'Jane' })
            }
          },
          response: {
            status: 400,
            headers: [
              { name: 'Content-Type', value: 'application/json' }
            ],
            content: {
              text: JSON.stringify({ error: 'Missing required field: email' })
            }
          }
        }
      ]
    }
  };

  harFilePath = path.join(testDir, 'requests.har');
  await fs.writeFile(harFilePath, JSON.stringify(harFile, null, 2));
})

beforeEach(async () => {
  // Create temporary test directory
  testRepoPath = await fs.mkdtemp(path.join(os.tmpdir(), 'test-repo-'));

  // Create test file structure
  await fs.mkdir(path.join(testRepoPath, 'src'), { recursive: true });
  await fs.mkdir(path.join(testRepoPath, 'tests'), { recursive: true });

  // Create sample source file
  testFilePath = path.join(testRepoPath, 'src', 'example.ts');
  await fs.writeFile(testFilePath, `
// Example TypeScript file
export function complexFunction(x: number, y: number): number {
  if (x > 10) {
    for (let i = 0; i < y; i++) {
      if (i % 2 === 0) {
        console.log(i);
      } else {
        console.log('odd');
      }
    }
  } else if (x < 5) {
    while (y > 0) {
      y--;
    }
  }
  return x + y;
}

export function simpleFunction(a: number): number {
  return a * 2;
}
  `.trim());

  // Create sample test file
  await fs.writeFile(path.join(testRepoPath, 'tests', 'example.test.ts'), `
import { complexFunction, simpleFunction } from '../src/example';

describe('example', () => {
  it('should work', () => {
    expect(complexFunction(1, 2)).toBe(3);
  });
});
  `.trim());

  // Initialize git repo
  const { execSync } = await import('child_process');
  try {
    execSync('git init', { cwd: testRepoPath, stdio: 'ignore' });
    execSync('git config user.name "Test User"', { cwd: testRepoPath, stdio: 'ignore' });
    execSync('git config user.email "test@example.com"', { cwd: testRepoPath, stdio: 'ignore' });
    execSync('git add .', { cwd: testRepoPath, stdio: 'ignore' });
    execSync('git commit -m "Initial commit"', { cwd: testRepoPath, stdio: 'ignore' });

    // Make some changes and commit for churn analysis
    await fs.appendFile(testFilePath, '\n// More code\n');
    execSync('git add .', { cwd: testRepoPath, stdio: 'ignore' });
    execSync('git commit -m "Second commit"', { cwd: testRepoPath, stdio: 'ignore' });
  } catch (error) {
    console.warn('Git operations failed in test setup:', error);
  }
})

afterEach(async () => {
  // Clean up test directory
  try {
    await fs.rm(testRepoPath, { recursive: true, force: true });
  } catch (error) {
    console.warn('Failed to clean up test directory:', error);
  }
})

