          res.writeHead(200, { "Content-Type": "application/json" });
          res.end(chatCompletion(JUDGE_PASS));
          return;
        }
        res.writeHead(404);
        res.end("no");
      });
    });
    server.listen(0, "127.0.0.1", () => {
      const { port } = server.address() as { port: number };
