    if (cmd === 'git') return Buffer.from('https://github.com/owner/repo.git\n')
    if (cmd === 'gh') return Buffer.from('gh version 2.0.0')
    return Buffer.from('')
  }
  _execFileImplT = (_cmd, _args, _opts, cb) => {
    n++
    if (n === 1) cb(null, 'true\n', '')
