afterEach(async () => {
    for (const c of collectors) c.disconnect();
    collectors = [];
    await Promise.all(
      servers.map(
        (wss) =>
          new Promise<void>((r) => {
            // Force-close any client sockets first (a paused/half-dead socket
            // would otherwise keep wss.close() pending forever).
            for (const client of wss.clients) client.terminate();
            wss.close(() => r());
          }),
      ),
    );
    servers = [];
  })

