      name: "Carl",
      slug: "goal-carl",
      created_at: "2026-01-03T00:00:00.000Z",
    });
    // Sidecar written before `slug` existed: falls back to slugified name.
    const legacy = {
      agent_id: "roster-goal-dee-jones",
      project_slug: "roster",
      name: "Dee Jones!",
      created_at: "2026-01-04T00:00:00.000Z",
