    fs.mkdirSync(skillScriptsDir, { recursive: true });
    fs.copyFileSync(scriptPath, path.join(skillScriptsDir, 'fetch-upstream.sh'));
    fs.chmodSync(path.join(skillScriptsDir, 'fetch-upstream.sh'), 0o755);
  })

