          sessionId: 'whatif-1',
          task: 'Add caching',
          success: true,
          reward: 0.95,
          latencyMs: 100
        },
        {
          sessionId: 'whatif-2',
          task: 'Add caching',
          success: true,
          reward: 0.92,
          latencyMs: 110
        },
        {
          sessionId: 'whatif-3',
          task: 'Remove validation',
          success: false,
          reward: 0.2,
          latencyMs: 3000
        }
      ];

      await Promise.all(patterns.map(p => reasoningBank.storePattern(p)));
      await new Promise(resolve => setTimeout(resolve, 200));
    })

