        ],
        handler: async (args) => {
          for (let i = 0; i < args.iterations; i++) {
            if (args.delay > 0) {
              await AsyncTestUtils.delay(args.delay);
            }

            if (i % 10 === 0) {
              cli.stdout(`Progress: ${i}/${args.iterations}`);
