beforeAll(async () => {
    runTmux(["new-session", "-d", "-s", sessionName, "-n", "agent", sleepCommand]);
    const pane = runTmux(["display-message", "-p", "-t", `=${sessionName}:agent`, "#{pane_id}"]);
    runTmux(["set-option", "-p", "-t", pane, "@tmux_ide_pane_id", "pane.readiness-live"]);

    registry = new WorkspaceRegistry({
      dir: join(root, "registry"),
      listSessions: () => [sessionName],
    });
    registry.add({ name: workspaceName, sessionName, projectDir: root });

    runtime = createNativeTerminalAttachmentRuntime({
      daemonInstanceId,
      webSocketUrl: "ws://127.0.0.1:6070/v1/terminal/attachments/redeem",
      registry,
      tmuxAuthority: {
        executablePath,
        socketSelector: { kind: "name", name: socketName },
        trustedCwd: root,
      },
    });
    await runtime.whenReady();

    app = new Hono();
    mountStartupReadinessRoute(app, {
      daemon: DAEMON,
      ownerToken: OWNER_TOKEN,
      registry,
      attachmentRuntime: runtime,
      // The canonical record is machine-global state; this suite proves the
      // catalog rungs, so identity is pinned to this generation.
      inspectCanonical: () =>
        ({
          status: "valid",
          info: { instanceId: daemonInstanceId },
          observation: { dev: 1, ino: 2, size: 3, mtimeMs: 4 },
        }) as never,
    });
  })

afterAll(async () => {
    await runtime?.dispose().catch(() => undefined);
    spawnSync(executablePath, ["-L", socketName, "kill-server"], { stdio: "ignore" });
    rmSync(root, { recursive: true, force: true });
  })

beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), "mux-verbs-"));
    registry = new WorkspaceRegistry({ dir, listSessions: () => ["work"] });
    registry.add({ name: "work", sessionName: "work", projectDir: dir });
    tmux = new FakeTmux("work");
    const editor = tmux.addWindow("editor");
    tmux.panes[0]!.options.set("@tmux_ide_pane_id", "pane.one");
    tmux.windows[0]!.options.set("@tmux_ide_window_id", "win.editor");
    const shell = tmux.addWindow("shell");
    tmux.panes[1]!.options.set("@tmux_ide_pane_id", "pane.two");
    tmux.windows[1]!.options.set("@tmux_ide_window_id", "win.shell");
    void editor;
    void shell;
    authority = new WorkspaceMultiplexerAuthority({
      daemonInstanceId: DAEMON_ID,
      registry,
      io: {
        runTmux: tmux.run,
        canonicalProjectDir: (path) => path,
        // The fake raises plain Errors where the bridge raises typed TmuxErrors;
        // this seam is how "the session is simply gone" stays distinguishable
        // from "tmux failed" without the test depending on the bridge.
        isMissingTmuxTarget: (error) => /no such session/u.test(String(error)),
      },
    });
  })

