beforeEach(() => {
    vi.useFakeTimers();
    runLocalColaSpy.mockClear();

    // Need enough existing nodes so 1 new node is <30% of the graph
    // (the incremental path requires newNodeIds.size < totalNodes * 0.3)
    cy = cytoscape({
      headless: true,
      elements: [
        { data: { id: 'file-a.md' }, position: { x: 500, y: 500 } },
        { data: { id: 'file-b.md' }, position: { x: 600, y: 400 } },
        { data: { id: 'file-c.md' }, position: { x: 400, y: 600 } },
        { data: { id: 'file-d.md' }, position: { x: 700, y: 300 } },
        { data: { id: 'edge-ab', source: 'file-a.md', target: 'file-b.md' } },
        { data: { id: 'edge-bc', source: 'file-b.md', target: 'file-c.md' } },
        { data: { id: 'edge-cd', source: 'file-c.md', target: 'file-d.md' } },
      ],
    });

    cleanup = enableAutoLayout(cy);

    // Force the initial layout to fire by adding a throwaway node + debounce.
    // enableAutoLayout only sets hasRunInitialLayout=true on first runLayout call,
    // which requires an event to trigger it. The initial elements were added before
    // the event listener was registered.
    cy.add({ group: 'nodes', data: { id: '__init__' }, position: { x: 300, y: 300 } });
    vi.advanceTimersByTime(400); // 300ms debounce + margin
    cy.remove(cy.$id('__init__'));
    vi.advanceTimersByTime(400); // Let the remove settle
    runLocalColaSpy.mockClear();
  })

beforeAll(async () => {
    root = await mkdtemp(path.join(tmpdir(), 'vt-fuzz-session-'))
    vault = path.join(root, 'vault')
    await mkdir(vault, { recursive: true })

    const notes = path.join(vault, 'notes')
    const projects = path.join(vault, 'projects')
    const projectsSub = path.join(projects, 'alpha')
    await mkdir(notes, { recursive: true })
    await mkdir(projectsSub, { recursive: true })

    const files = [
      { dir: notes, name: 'one.md', content: '---\nposition:\n  x: 10\n  y: 20\n---\n# One\nContent.\n' },
      { dir: notes, name: 'two.md', content: '---\nposition:\n  x: 30\n  y: 40\n---\n# Two\nContent.\n' },
      { dir: projects, name: 'root.md', content: '---\nposition:\n  x: 50\n  y: 60\n---\n# Root\nProject root.\n' },
      { dir: projectsSub, name: 'task.md', content: '---\nposition:\n  x: 70\n  y: 80\n---\n# Task\nAlpha task.\n' },
    ]

    for (const f of files) {
      await writeFile(path.join(f.dir, f.name), f.content, 'utf8')
    }

    nodeIds = files.map((f) => path.join(f.dir, f.name))
    folderIds = [`${notes}/`, `${projects}/`, `${projectsSub}/`]

    clearWatchFolderState()
    setGraph(createEmptyGraph())

    handle = await startDaemon({
      vault,
      appSupportPath: path.join(root, 'app-support'),
    })
    baseUrl = `http://127.0.0.1:${handle.port}`

    for (const dir of [notes, projects]) {
      await fetch(`${baseUrl}/vault/read-paths`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ path: dir }),
      })
    }

    await waitFor(async () => {
      const body = (await (await fetch(`${baseUrl}/graph`)).json()) as { nodes: Record<string, unknown> }
      const foundAll = nodeIds.every((id) => body.nodes[id] !== undefined)
      return foundAll ? body : null
    }, 10000)
  }, 30000)

afterAll(async () => {
    await handle?.stop().catch(() => {})
    clearWatchFolderState()
    setGraph(createEmptyGraph())
    await rm(root, { recursive: true, force: true })
  })

